/**
 * Signals in message PEDAL_STATUS.
 *
 * PDLB driver-input and propulsion-safety status. Sent every 20 ms. throttle_command is the calibrated 15-bit command and is forced to zero while throttle_inhibit is asserted.
 *
 * All signal values are as on the CAN bus.
 */
struct network_pedal_status_t {
    /**
     * Range: 0..32767 (0..32767 -)
     * Scale: 1
     * Offset: 0
     */
    uint16_t throttle_command;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t throttle_inhibit;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t deadman_active;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t adc_fault;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t brake_active;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t is_calibrating;

    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t inhibit_reason;

    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t seq_counter;

    /**
     * Range: 0..65535 (0..65535 count)
     * Scale: 1
     * Offset: 0
     */
    uint16_t throttle_adc_raw;
};

